func TestCLI_ArgumentParsing(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantExit   int
		wantStderr string
	}{
		{"no args", []string{}, 2, "Usage:"},
		{"unknown command", []string{"bogus"}, 2, "unknown command"},
		{"get missing key", []string{"get"}, 2, "requires a key"},
		{"set missing value", []string{"set", "key"}, 2, "requires key and value"},
		{"delete missing key", []string{"delete"}, 2, "requires a key"},
		{"flags only no command", []string{"--quiet", "--verbose"}, 2, "no command specified"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			cli := NewCLI(stdout, stderr, t.TempDir())

			got := cli.Run(tt.args)
			if got != tt.wantExit {
				t.Errorf("exit = %d, want %d", got, tt.wantExit)
			}
			if !bytes.Contains(stderr.Bytes(), []byte(tt.wantStderr)) {
				t.Errorf("stderr = %q, want containing %q", stderr.String(), tt.wantStderr)
			}
		})
	}
}

func TestCLI_Init(t *testing.T) {
	t.Run("creates config file", func(t *testing.T) {
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		dir := t.TempDir()
		cli := NewCLI(stdout, stderr, dir)

		exit := cli.Run([]string{"init"})
		if exit != 0 {
			t.Fatalf("exit = %d, stderr: %s", exit, stderr.String())
		}
		if _, err := os.Stat(filepath.Join(dir, "config.yaml")); err != nil {
			t.Error("config file not created")
		}
	})

	t.Run("fails if exists", func(t *testing.T) {
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		dir := t.TempDir()
		os.WriteFile(filepath.Join(dir, "config.yaml"), []byte("existing"), 0644)
		cli := NewCLI(stdout, stderr, dir)

		exit := cli.Run([]string{"init"})
		if exit != 1 {
			t.Errorf("exit = %d, want 1", exit)
		}
	})

	t.Run("quiet suppresses output", func(t *testing.T) {
		stdout := &bytes.Buffer{}
		cli := NewCLI(stdout, &bytes.Buffer{}, t.TempDir())
		cli.Run([]string{"--quiet", "init"})
		if stdout.Len() != 0 {
			t.Error("quiet flag didn't suppress output")
		}
	})
}

func TestCLI_GetSetDelete(t *testing.T) {
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	dir := t.TempDir()
	cli := NewCLI(stdout, stderr, dir)

	// Set creates file if missing
	if exit := cli.Run([]string{"set", "name", "Deadwood"}); exit != 0 {
		t.Fatalf("set failed: %s", stderr.String())
	}

	// Get retrieves value
	stdout.Reset()
	if exit := cli.Run([]string{"get", "name"}); exit != 0 {
		t.Fatal("get failed")
	}
	if !bytes.Contains(stdout.Bytes(), []byte("Deadwood")) {
		t.Errorf("got %q, want Deadwood", stdout.String())
	}

	// Get missing key
	stderr.Reset()
	if exit := cli.Run([]string{"get", "missing"}); exit != 1 {
		t.Error("get missing should return 1")
	}

	// Delete
	if exit := cli.Run([]string{"delete", "name"}); exit != 0 {
		t.Fatal("delete failed")
	}

	// Delete missing
	if exit := cli.Run([]string{"delete", "name"}); exit != 1 {
		t.Error("delete missing should return 1")
	}
}

func TestCLI_Validate(t *testing.T) {
	t.Run("valid yaml", func(t *testing.T) {
		dir := t.TempDir()
		os.WriteFile(filepath.Join(dir, "config.yaml"), []byte("key: value\n"), 0644)
		stdout := &bytes.Buffer{}
		cli := NewCLI(stdout, &bytes.Buffer{}, dir)

		if exit := cli.Run([]string{"validate"}); exit != 0 {
			t.Error("validate should pass")
		}
		if !bytes.Contains(stdout.Bytes(), []byte("valid")) {
			t.Error("should output valid message")
		}
	})

	t.Run("invalid yaml", func(t *testing.T) {
		dir := t.TempDir()
		os.WriteFile(filepath.Join(dir, "config.yaml"), []byte(":::invalid"), 0644)
		stderr := &bytes.Buffer{}
		cli := NewCLI(&bytes.Buffer{}, stderr, dir)

		if exit := cli.Run([]string{"validate"}); exit != 1 {
			t.Error("invalid yaml should return 1")
		}
	})
}

func TestCLI_OutputFormats(t *testing.T) {
	dir := t.TempDir()
	os.WriteFile(filepath.Join(dir, "config.yaml"), []byte("name: Doc\n"), 0644)

	formats := []struct {
		format   string
		contains string
	}{
		{"json", `"name"`},
		{"yaml", "name:"},
		{"text", "name:"},
	}

	for _, f := range formats {
		t.Run(f.format, func(t *testing.T) {
			stdout := &bytes.Buffer{}
			cli := NewCLI(stdout, &bytes.Buffer{}, dir)
			cli.Run([]string{"--format", f.format, "list"})
			if !bytes.Contains(stdout.Bytes(), []byte(f.contains)) {
				t.Errorf("%s format: got %q", f.format, stdout.String())
			}
		})
	}
}
